using Dict=CefRefPtr<CefDictionaryValue>;
struct Harness{
 struct Request{int id;std::string method,session;Dict params;};int next=0;double now=0;std::vector<Request> requests;std::vector<Dict> events;std::vector<std::string> errors;
 suitecut::PageErrorControls controls{
  [this]{return ++next;},[this](int id,const std::string& method,Dict params,const std::string& session){requests.push_back({id,method,session,params->Copy(false)});return true;},
  [this](Dict event,Dict,const std::string&){events.push_back(event->Copy(false));},[this](const std::string& error){errors.push_back(error);},[](Dict){return std::string("actual opaque object preview");},[this]{return now;}};
 static std::string JSON(Dict value){auto w=CefValue::Create();w->SetDictionary(value);return CefWriteJSON(w,JSON_WRITER_DEFAULT).ToString();}
 Request Take(const std::string& method){const auto it=std::find_if(requests.begin(),requests.end(),[&](const Request&r){return r.method==method;});assert(it!=requests.end());auto r=*it;requests.erase(it);return r;}
 void Ack(Request request,Dict reply= CefDictionaryValue::Create(),bool ok=true){assert(controls.Complete(request.id,ok,JSON(reply),request.session));}
};
Dict Exception(const std::string& type="object",const std::string& subtype="error"){
 auto e=CefDictionaryValue::Create();e->SetString("type",type);e->SetString("subtype",subtype);if(type=="object")e->SetString("objectId","actual-error-object");auto d=CefDictionaryValue::Create();d->SetInt("executionContextId",19);d->SetDictionary("exception",e);return d;
}
Dict Remote(const std::string& id){auto v=CefDictionaryValue::Create();v->SetString("type","object");v->SetString("subtype","error");v->SetString("objectId",id);v->SetString("description","ABBREVIATED description unrelated to exact fields");auto r=CefDictionaryValue::Create();r->SetDictionary("result",v);return r;}
Dict Descriptors(const std::u16string& units){auto list=CefListValue::Create();int n=0;for(const auto& key:{"name","message","stack"}){auto value=CefDictionaryValue::Create();value->SetString("type","string");suitecut::DevToolsSetString(value,"value",std::string(key)+suitecut::DevToolsUnitsWTF8(units));auto property=CefDictionaryValue::Create();property->SetString("name",key);property->SetDictionary("value",value);list->SetDictionary(n++,property);}auto reply=CefDictionaryValue::Create();reply->SetList("result",list);return reply;}
