 {Harness h;h.controls.Start(Exception(),"actual-session");assert(h.controls.Captures()==1&&h.controls.Physical()==1&&h.controls.Groups()==0&&h.controls.GroupReservations()==1);auto alias=h.Take("Runtime.callFunctionOn");assert(alias.params->GetString("functionDeclaration")=="function(){return this;}");h.Ack(alias,Remote("actual-alias"));assert(h.controls.Physical()==2);auto props=h.Take("Runtime.getProperties");assert(!props.params->GetBool("ownProperties"));h.Ack(props,Descriptors(units));assert(h.events.size()==1);for(const auto& key:{"name","message","stack"})assert(suitecut::DevToolsString(h.events[0]->GetValue(key))==std::string(key)+suitecut::DevToolsUnitsWTF8(units));assert(h.controls.Captures()==1&&h.controls.Groups()==1);h.Ack(h.Take("Runtime.releaseObject"));h.Ack(h.Take("Runtime.releaseObjectGroup"));assert(h.controls.Captures()==0&&h.controls.Physical()==0&&h.controls.Groups()==0&&h.controls.Bytes()==0&&h.errors.empty());}
 {Harness h;for(int i=0;i<64;++i)h.controls.Start(Exception(),"held");assert(h.controls.Captures()==64&&h.controls.Physical()==64);h.now=30001;h.controls.Tick();assert(!h.controls.NeedsTick());h.controls.Start(Exception(),"new");assert(h.controls.Captures()==64&&h.controls.Physical()==64);for(int i=0;i<64;++i){h.Ack(h.Take("Runtime.callFunctionOn"),Remote("late-alias"));h.Ack(h.Take("Runtime.releaseObject"));h.Ack(h.Take("Runtime.releaseObjectGroup"));}assert(h.events.empty()&&h.controls.Captures()==0&&h.controls.Physical()==0&&h.controls.Groups()==0&&h.controls.Bytes()==0);}
 {Harness h;h.controls.Start(Exception(),"detached");assert(!h.controls.Accepts(h.requests[0].id,"other"));h.controls.Detached("other");assert(h.controls.Physical()==1);h.controls.Detached("detached");assert(h.controls.Physical()==0&&h.controls.Captures()==0&&h.controls.Bytes()==0);assert(!h.controls.Complete(h.requests[0].id,true,"{}","detached"));}
 {Harness h;auto details=Exception("string","");suitecut::DevToolsSetString(details->GetDictionary("exception"),"value",suitecut::DevToolsUnitsWTF8(units));h.controls.Start(details,"main");assert(h.events.size()==1&&h.controls.Captures()==0);assert(suitecut::DevToolsString(h.events[0]->GetValue("message"))==suitecut::DevToolsUnitsWTF8(units));}
 {Harness h;h.controls.Start(Exception(),"main");h.Ack(h.Take("Runtime.callFunctionOn"),Remote("real"));auto p=Descriptors(units);auto property=p->GetList("result")->GetDictionary(0);property->Remove("value");auto getter=CefDictionaryValue::Create();getter->SetString("objectId","author-getter-never-invoked");property->SetDictionary("get",getter);h.Ack(h.Take("Runtime.getProperties"),p);assert(h.events.empty()&&!h.errors.empty());h.Ack(h.Take("Runtime.releaseObject"));h.Ack(h.Take("Runtime.releaseObjectGroup"));assert(h.controls.Captures()==0&&h.controls.Physical()==0);}
 {Harness h;h.controls.Start(Exception(),"ordered");h.controls.Start(Exception(),"ordered");auto first=h.Take("Runtime.callFunctionOn");auto second=h.Take("Runtime.callFunctionOn");h.Ack(second,Remote("second-alias"));h.Ack(h.Take("Runtime.getProperties"),Descriptors(u"second"));assert(h.events.empty());h.Ack(h.Take("Runtime.releaseObject"));h.Ack(first,Remote("first-alias"));h.Ack(h.Take("Runtime.getProperties"),Descriptors(u"first"));assert(h.events.size()==2);assert(h.events[0]->GetString("message")=="messagefirst"&&h.events[1]->GetString("message")=="messagesecond");while(!h.requests.empty()){auto r=h.requests.front();h.requests.erase(h.requests.begin());assert(r.method=="Runtime.releaseObject"||r.method=="Runtime.releaseObjectGroup");h.Ack(r);}assert(h.controls.Physical()==0&&h.controls.Groups()==0&&h.controls.Bytes()==0);}
 {Harness h;auto d=Exception("object","");auto tag=CefDictionaryValue::Create();tag->SetString(suitecut::kDevToolsUTF16Tag,"d800");d->GetDictionary("exception")->SetDictionary("value",tag);h.controls.Start(d,"opaque");assert(h.events.size()==1&&h.events[0]->GetString("message")=="actual opaque object preview");assert(h.controls.Physical()==1);h.Ack(h.Take("Runtime.releaseObject"));assert(h.controls.Captures()==0);}
 {Harness h;h.controls.Start(Exception(),"navigation");h.controls.ContextDestroyed("navigation",18);assert(h.controls.Captures()==1);h.controls.ContextDestroyed("navigation",19);assert(h.controls.Captures()==1&&h.controls.Physical()==1&&h.controls.Groups()==0);h.Ack(h.Take("Runtime.callFunctionOn"),Remote("old-context-alias"));assert(h.events.empty()&&h.requests.empty()&&h.errors.empty()&&h.controls.Captures()==0&&h.controls.Physical()==0&&h.controls.Bytes()==0);}
 std::cout<<"PASS genuine error descriptor fields, isolated UTF16, separate64 physical admission/late cleanup, exact sessions/detach, accessor rejection and release ACK ownership\n";
